import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene position and transforms
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ = [0, 0, 0], scaleXYZ = [1, 1, 1] } = config.scenePosition;
    group.position.set(x, y, z);
    group.rotation.set(rotationXYZ[0], rotationXYZ[1], rotationXYZ[2]);
    group.scale.set(scaleXYZ[0], scaleXYZ[1], scaleXYZ[2]);
  }

  const resources = [];

  // Create textured background plane
  const texture = ctx.textureLoader.load(config.imageUrl);
  resources.push(texture);

  const geometry = new THREE.PlaneGeometry(1, 1);
  resources.push(geometry);

  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
    transparent: true,
  });
  resources.push(material);

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text label
  if (config.textContent) {
    const textMesh = ctx.fontAtlas.createTextMesh(config.textContent, {
      fontSize: 0.34,
      fontWeight: 400,
      fontFamily: 'Lora',
      color: '#16161d',
      align: 'center',
      verticalAlign: 'middle',
    });

    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    config.cinematicPrimitives.forEach(primitive => {
      if (ctx.primitives[primitive.name]) {
        ctx.primitives[primitive.name](group, primitive.params || {});
      }
    });
  }

  // Resource cleanup
  group.userData.cleanup = () => {
    resources.forEach(resource => resource.dispose());
  };

  group.userData.handlers = {};

  return group;
}
